exercises.solution:
const sacola = {
  banca: 'Banca da Dona Rosa',
  itens: [
    { produto: 'Tomate', quantidade: 2, preco: 7.5 },
    { produto: 'Alface', quantidade: 1, preco: 3 },
    { produto: 'Banana', quantidade: 3, preco: 4.2 },
  ],
};

const total = sacola.itens.reduce((soma, item) => soma + item.preco * item.quantidade, 0);

console.log('Feira:', sacola.banca);
console.log('Itens na sacola:', sacola.itens.length);
console.table(sacola.itens);
console.log('Total: R$', total.toFixed(2));

